"use strict";(self.webpackChunksdvplot_docs=self.webpackChunksdvplot_docs||[]).push([["1318"],{3870(e,a,n){n.r(a),n.d(a,{metadata:()=>s,default:()=>m,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>i});var s=JSON.parse('{"id":"cookbooks/reactable-sparklines","title":"reactable sparklines and gauges cookbook","description":"In-cell charts with reactable: NBA point-margin sparklines, WNBA scoring sparkbars, NFL weekly EPA bars above and below zero, and gauges for NBA win percentage and NHL save percentage.","source":"@site/docs/cookbooks/reactable-sparklines.md","sourceDirName":"cookbooks","slug":"/cookbooks/reactable-sparklines","permalink":"/docs/cookbooks/reactable-sparklines","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":14,"frontMatter":{"title":"reactable sparklines and gauges cookbook","sidebar_label":"reactable sparklines and gauges","sidebar_position":14,"description":"In-cell charts with reactable: NBA point-margin sparklines, WNBA scoring sparkbars, NFL weekly EPA bars above and below zero, and gauges for NBA win percentage and NHL save percentage."},"sidebar":"docs","previous":{"title":"reactable formatters","permalink":"/docs/cookbooks/reactable-formatters"},"next":{"title":"reactable themes and titles","permalink":"/docs/cookbooks/reactable-themes"}}'),t=n(74848),l=n(28453);let r={title:"reactable sparklines and gauges cookbook",sidebar_label:"reactable sparklines and gauges",sidebar_position:14,description:"In-cell charts with reactable: NBA point-margin sparklines, WNBA scoring sparkbars, NFL weekly EPA bars above and below zero, and gauges for NBA win percentage and NHL save percentage."},o="reactable sparklines and gauges",i={},c=[{value:"1. Sparklines: every NBA team&#39;s game-by-game point margin",id:"1-sparklines-every-nba-teams-game-by-game-point-margin",level:2},{value:"2. Sparkbars: WNBA scoring over each team&#39;s last 12 games",id:"2-sparkbars-wnba-scoring-over-each-teams-last-12-games",level:2},{value:"3. Bars above and below zero: NFL offensive EPA per play, week by week",id:"3-bars-above-and-below-zero-nfl-offensive-epa-per-play-week-by-week",level:2},{value:"4. Gauges: NBA win percentage",id:"4-gauges-nba-win-percentage",level:2},{value:"5. Gauges on a narrow scale: NHL save percentage",id:"5-gauges-on-a-narrow-scale-nhl-save-percentage",level:2},{value:"Run it yourself",id:"run-it-yourself",level:2}];function d(e){let a={a:"a",code:"code",div:"div",h1:"h1",h2:"h2",header:"header",iframe:"iframe",p:"p",pre:"pre",...(0,l.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(a.header,{children:(0,t.jsx)(a.h1,{id:"reactable-sparklines-and-gauges",children:"reactable sparklines and gauges"})}),"\n",(0,t.jsxs)(a.p,{children:["reactablefmtr draws small charts inside table cells: ",(0,t.jsx)(a.code,{children:"react_sparkline"}),", ",(0,t.jsx)(a.code,{children:"react_sparkbar"})," and ",(0,t.jsx)(a.code,{children:"gauge_chart"}),".\n",(0,t.jsx)(a.code,{children:"sdvplot.reactable"})," ports the three as ",(0,t.jsx)(a.code,{children:"reactable_sdv_sparkline"}),", ",(0,t.jsx)(a.code,{children:"reactable_sdv_sparkbar"})," and ",(0,t.jsx)(a.code,{children:"reactable_sdv_gauge"}),".\nEach cell is a small inline SVG, so the table needs no extra JavaScript, and each SVG is an image with an\n",(0,t.jsx)(a.code,{children:"aria-label"})," that a screen reader reads out (the number of points, the low, the high and the last value). Hovering a\nchart shows the same summary."]}),"\n",(0,t.jsxs)(a.p,{children:["A sparkline or sparkbar column holds one list of numbers per row: a polars ",(0,t.jsx)(a.code,{children:"List"})," column or a pandas column of lists\nboth pass through reactable-py unchanged. Give ",(0,t.jsx)(a.code,{children:"team_col"})," and ",(0,t.jsx)(a.code,{children:"league"})," and each row's chart takes that team's color.\nThe recipes below use real 2025-26 NBA, 2026 WNBA, 2025 NFL and 2025-26 NHL data loaded through sportsdataverse-py."]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:"import polars as pl\nimport sportsdataverse.nba as nba\nimport sportsdataverse.nfl as nfl\nimport sportsdataverse.nhl as nhl\nimport sportsdataverse.wnba as wnba\nfrom reactable import Column, Reactable, embed_css\n\nfrom sdvplot.reactable import (\n    reactable_sdv_gauge,\n    reactable_sdv_logos,\n    reactable_sdv_sparkbar,\n    reactable_sdv_sparkline,\n)\n\nSEASON = 2026  # the 2025-26 NBA and NHL seasons and the 2026 WNBA season\nNFL_SEASON = 2025  # nflverse names a season by the year it starts\nembed_css()\n"})}),"\n",(0,t.jsx)(a.h2,{id:"1-sparklines-every-nba-teams-game-by-game-point-margin",children:"1. Sparklines: every NBA team's game-by-game point margin"}),"\n",(0,t.jsxs)(a.p,{children:["One row per team, one list per row: the team's point margin in each of its 82 regular-season games, in date\norder (",(0,t.jsx)(a.code,{children:"standard_games"})," drops the All-Star Game and the NBA Cup final, which ESPN files under the regular season).\n",(0,t.jsx)(a.code,{children:"highlight_points"})," marks the season's worst and best nights, and ",(0,t.jsx)(a.code,{children:'statline="mean"'})," draws a dashed line at the team's\naverage margin with its value in the right margin. The line takes each team's primary color from ",(0,t.jsx)(a.code,{children:"team_col"}),"."]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:'def standard_games(schedule):\n    # the regular season\'s standard games: ESPN also files the All-Star Game and the in-season cup final there\n    games = schedule.filter((pl.col("season_type") == 2) & (pl.col("type_abbreviation") == "STD"))\n    return pl.col("game_id").is_in(games["game_id"].implode())\n\n\nnba_games = nba.load_nba_team_boxscore(seasons=[SEASON]).filter(standard_games(nba.load_nba_schedule(seasons=[SEASON])))\nnba_margins = (\n    nba_games.sort("game_date")\n    .group_by("team_abbreviation", maintain_order=True)\n    .agg(\n        gp=pl.len(),\n        w=(pl.col("team_winner") == True).sum(),  # noqa: E712\n        margin=pl.col("team_score") - pl.col("opponent_team_score"),\n    )\n    .with_columns(avg=pl.col("margin").list.mean().round(1), logo=pl.col("team_abbreviation"))\n    .sort("avg", descending=True)\n    .select("logo", "team_abbreviation", "w", "gp", "avg", "margin")\n)\nassert nba_margins.height == 30 and nba_margins["gp"].min() == nba_margins["gp"].max() == 82\nReactable(\n    nba_margins,\n    columns=[\n        reactable_sdv_logos(league="nba", id="logo", name="", width=50, height=26),\n        Column(id="team_abbreviation", show=False),\n        Column(id="w", name="W", width=55),\n        Column(id="gp", name="GP", width=55),\n        Column(id="avg", name="Avg. margin", width=95),\n        reactable_sdv_sparkline(\n            nba_margins,\n            id="margin",\n            name="Margin, game by game",\n            team_col="team_abbreviation",\n            league="nba",\n            highlight_points={"min": "#d7191c", "max": "#1a9641"},\n            statline="mean",\n            decimals=1,\n            line_width=1,\n            width=260,\n            height=34,\n            min_width=280,\n        ),\n    ],\n    default_page_size=10,\n    compact=True,\n)\n'})}),"\n",(0,t.jsxs)(a.div,{className:"sdv-output",children:["\n",(0,t.jsx)(a.iframe,{className:"sdv-frame",src:"/outputs/cookbooks/reactable-sparklines/3_0.html",title:"Interactive widget",height:"480",loading:"lazy"}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"2-sparkbars-wnba-scoring-over-each-teams-last-12-games",children:"2. Sparkbars: WNBA scoring over each team's last 12 games"}),"\n",(0,t.jsxs)(a.p,{children:[(0,t.jsx)(a.code,{children:"reactable_sdv_sparkbar"})," draws the same kind of list as bars. Here each bar is a team's points in one of its last\n12 regular-season games; ",(0,t.jsx)(a.code,{children:"highlight_bars"})," colors the best game gold, and ",(0,t.jsx)(a.code,{children:'labels="last"'})," prints the most recent\nscore above its bar. Bars stand on zero, so a 70-point night is visibly shorter than a 100-point one."]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:'wnba_games = wnba.load_wnba_team_boxscore(seasons=[SEASON]).filter(\n    standard_games(wnba.load_wnba_schedule(seasons=[SEASON]))\n)\nwnba_last = (\n    wnba_games.sort("game_date")\n    .group_by("team_abbreviation", maintain_order=True)\n    .agg(pts=pl.col("team_score").tail(12), ppg=pl.col("team_score").mean().round(1))\n    .with_columns(last12=pl.col("pts").list.mean().round(1), logo=pl.col("team_abbreviation"))\n    .sort("last12", descending=True)\n    .select("logo", "team_abbreviation", "ppg", "last12", "pts")\n)\nassert wnba_last.height == 15 and wnba_last["pts"].list.len().min() == 12\nReactable(\n    wnba_last,\n    columns=[\n        reactable_sdv_logos(league="wnba", id="logo", name="", width=50, height=26),\n        Column(id="team_abbreviation", show=False),\n        Column(id="ppg", name="Season PPG", width=100),\n        Column(id="last12", name="Last 12 PPG", width=100),\n        reactable_sdv_sparkbar(\n            wnba_last,\n            id="pts",\n            name="Points, last 12 games",\n            team_col="team_abbreviation",\n            league="wnba",\n            highlight_bars={"max": "#f2b705"},\n            labels="last",\n            width=200,\n            height=34,\n            min_width=220,\n        ),\n    ],\n    pagination=False,\n    compact=True,\n)\n'})}),"\n",(0,t.jsxs)(a.div,{className:"sdv-output",children:["\n",(0,t.jsx)(a.iframe,{className:"sdv-frame",src:"/outputs/cookbooks/reactable-sparklines/5_0.html",title:"Interactive widget",height:"480",loading:"lazy"}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"3-bars-above-and-below-zero-nfl-offensive-epa-per-play-week-by-week",children:"3. Bars above and below zero: NFL offensive EPA per play, week by week"}),"\n",(0,t.jsxs)(a.p,{children:["Expected points added per play goes below zero, and a sparkbar hangs those weeks under the zero line. nflverse's\nweekly team stats give each team's passing and rushing EPA and its dropbacks and carries; the list holds one rate per\ngame the team played. ",(0,t.jsx)(a.code,{children:'bandline="innerquartiles"'})," shades the middle half of each team's weeks, so a steady offense\nshows a thin band and an erratic one a wide band."]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:'weeks = nfl.load_nfl_team_stats([NFL_SEASON]).filter(pl.col("season_type") == "REG")\nplays = pl.col("attempts") + pl.col("sacks_suffered") + pl.col("carries")\nepa = pl.col("passing_epa") + pl.col("rushing_epa")\nnfl_weekly = (\n    weeks.sort("week")\n    .group_by("team", maintain_order=True)\n    .agg(season_epa=(epa.sum() / plays.sum()).round(3), weekly=(epa / plays).round(3))\n    .with_columns(logo=pl.col("team"))\n    .sort("season_epa", descending=True)\n    .select("logo", "team", "season_epa", "weekly")\n)\nassert nfl_weekly.height == 32 and nfl_weekly["weekly"].list.len().min() == 17\nReactable(\n    nfl_weekly,\n    columns=[\n        reactable_sdv_logos(league="nfl", id="logo", name="", width=50, height=26),\n        Column(id="team", show=False),\n        Column(id="season_epa", name="EPA / play", width=95),\n        reactable_sdv_sparkbar(\n            nfl_weekly,\n            id="weekly",\n            name="EPA / play by week",\n            team_col="team",\n            league="nfl",\n            bandline="innerquartiles",\n            bandline_color="#888888",\n            width=260,\n            height=34,\n            min_width=280,\n        ),\n    ],\n    default_page_size=8,\n    compact=True,\n)\n'})}),"\n",(0,t.jsxs)(a.div,{className:"sdv-output",children:["\n",(0,t.jsx)(a.iframe,{className:"sdv-frame",src:"/outputs/cookbooks/reactable-sparklines/7_0.html",title:"Interactive widget",height:"480",loading:"lazy"}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"4-gauges-nba-win-percentage",children:"4. Gauges: NBA win percentage"}),"\n",(0,t.jsxs)(a.p,{children:[(0,t.jsx)(a.code,{children:"reactable_sdv_gauge"})," turns one number per row into a half-circle gauge with the value inside. With ",(0,t.jsx)(a.code,{children:"min_value"})," and\n",(0,t.jsx)(a.code,{children:"max_value"})," the scale is fixed (a win percentage runs from 0 to 1); without them it runs from 0 to the column's\nlargest absolute value (a negative value fills the gauge by its size, as in reactablefmtr). ",(0,t.jsx)(a.code,{children:"team_col"})," fills each gauge in the team's color, and ",(0,t.jsx)(a.code,{children:"number_fmt"})," takes a function or a format spec.\nThe ten best regular-season records:"]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:'nba_pct = (\n    nba_margins.with_columns(pct=(pl.col("w") / pl.col("gp")).round(3))\n    .sort("pct", descending=True)\n    .select("logo", "team_abbreviation", "w", "gp", "pct")\n    .head(10)\n)\nReactable(\n    nba_pct,\n    columns=[\n        reactable_sdv_logos(league="nba", id="logo", name="", width=50, height=26),\n        Column(id="team_abbreviation", show=False),\n        Column(id="w", name="W", width=60),\n        Column(id="gp", name="GP", width=60),\n        reactable_sdv_gauge(\n            nba_pct,\n            id="pct",\n            name="Win %",\n            team_col="team_abbreviation",\n            league="nba",\n            min_value=0,\n            max_value=1,\n            number_fmt="{:.0%}".format,\n            show_min_max=True,\n            size=2,\n            align="center",\n            min_width=130,\n        ),\n    ],\n    compact=True,\n)\n'})}),"\n",(0,t.jsxs)(a.div,{className:"sdv-output",children:["\n",(0,t.jsx)(a.iframe,{className:"sdv-frame",src:"/outputs/cookbooks/reactable-sparklines/9_0.html",title:"Interactive widget",height:"480",loading:"lazy"}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"5-gauges-on-a-narrow-scale-nhl-save-percentage",children:"5. Gauges on a narrow scale: NHL save percentage"}),"\n",(0,t.jsxs)(a.p,{children:["Save percentage lives in a narrow band, so a gauge from 0 to 1 would look full for every team. Fixing the scale to\n.880-.920 spreads the 32 teams out, and a two-color ",(0,t.jsx)(a.code,{children:"fill_color"})," ramps from red (the column's lowest) to green (its\nhighest). NHL regular-season game ids carry ",(0,t.jsx)(a.code,{children:"02"})," after the season's year. The goalie box score counts the shots each\ngoaltender faced, so a team's save percentage is its goalies' saves over the shots against them, summed over the\nseason. An empty-net goal is not a shot any goalie faced, and an own goal is not a shot at all: neither is in the\ndenominator, as in the NHL's own goaltending figures."]}),"\n",(0,t.jsx)(a.pre,{children:(0,t.jsx)(a.code,{className:"language-python",children:'nhl_goalies = nhl.load_nhl_goalie_box(seasons=[SEASON]).filter(\n    pl.col("game_id").cast(pl.String).str.slice(4, 2) == "02"\n)\nnhl_sv = (\n    nhl_goalies.group_by("team_abbrev")\n    .agg(\n        gp=pl.col("game_id").n_unique(),\n        sv_pct=(pl.col("saves").sum() / pl.col("shots_against").sum()).round(3),\n    )\n    .with_columns(logo=pl.col("team_abbrev"))\n    .sort("sv_pct", descending=True)\n    .select("logo", "team_abbrev", "gp", "sv_pct")\n)\nassert nhl_sv.height == 32 and nhl_sv["gp"].min() == 82\nReactable(\n    nhl_sv,\n    columns=[\n        reactable_sdv_logos(league="nhl", id="logo", name="", width=50, height=26),\n        Column(id="team_abbrev", show=False),\n        Column(id="gp", name="GP", width=60),\n        reactable_sdv_gauge(\n            nhl_sv,\n            id="sv_pct",\n            name="Save %",\n            fill_color=["#d7191c", "#1a9641"],\n            min_value=0.88,\n            max_value=0.92,\n            number_fmt=".3f",\n            show_min_max=True,\n            size=2,\n            align="center",\n            min_width=130,\n        ),\n    ],\n    default_page_size=8,\n    compact=True,\n)\n'})}),"\n",(0,t.jsxs)(a.div,{className:"sdv-output",children:["\n",(0,t.jsx)(a.iframe,{className:"sdv-frame",src:"/outputs/cookbooks/reactable-sparklines/11_0.html",title:"Interactive widget",height:"480",loading:"lazy"}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"run-it-yourself",children:"Run it yourself"}),"\n",(0,t.jsxs)(a.p,{children:[(0,t.jsx)(a.a,{href:"pathname:///notebooks/cookbooks/reactable-sparklines.ipynb",download:!0,children:"Download the notebook"})," (outputs cleared) or ",(0,t.jsx)(a.a,{href:"https://github.com/sportsdataverse/sdvplot/blob/main/examples/notebooks/cookbooks/reactable-sparklines.ipynb",children:"open it on GitHub"}),"."]})]})}function m(e={}){let{wrapper:a}={...(0,l.R)(),...e.components};return a?(0,t.jsx)(a,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},28453(e,a,n){n.d(a,{R:()=>r,x:()=>o});var s=n(96540);let t={},l=s.createContext(t);function r(e){let a=s.useContext(l);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function o(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:r(e.components),s.createElement(l.Provider,{value:a},e.children)}}}]);